const RE = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$/;
function bad(s){ return !s || typeof s !== "string" || !RE.test(s); }
const i = $input.first().json;
const node = (i.node && String(i.node).trim()) || "";
if (node && bad(node)) return [{json: {blocked: true, ok: false, detail: "invalid node name"}}];
const sortBy = String(i.sortBy || "memory").toLowerCase() === "cpu" ? "cpu" : "memory";
const limit = Math.min(Math.max(parseInt(i.limit) || 10, 1), 30);
let url = "https://kubernetes.default.svc/api/v1/pods?limit=1000";
if (node) url += `&fieldSelector=${encodeURIComponent("spec.nodeName=" + node)}`;
return [{json: {url, node, sortBy, limit}}];

const r = $input.first().json;
if (r.blocked) return [{json: r}];
if (r.statusCode >= 400) return [{json: {blocked: true, ok: false, detail: `K8s API ${r.statusCode}: ${JSON.stringify(r.body?.message || r.body).slice(0,200)}`}}];
return [{json: {url: "https://kubernetes.default.svc/apis/metrics.k8s.io/v1beta1/pods"}}];

const m = $input.first().json;
if (m.blocked) return [{json: {ok: false, detail: m.detail}}];
if (m.statusCode >= 400) return [{json: {ok: false, detail: `metrics API ${m.statusCode} (metrics-server?)`}}];
const p = $('Prepare').first().json; const pods = $('K8s GET pods').first().json.body.items || [];
const toMi = (q) => { const s = String(q||"0"); if (s.endsWith("Ki")) return parseFloat(s)/1024; if (s.endsWith("Mi")) return parseFloat(s); if (s.endsWith("Gi")) return parseFloat(s)*1024; return parseFloat(s)/1048576; };
const toM = (q) => { const s = String(q||"0"); if (s.endsWith("n")) return parseFloat(s)/1e6; if (s.endsWith("u")) return parseFloat(s)/1e3; if (s.endsWith("m")) return parseFloat(s); return parseFloat(s)*1000; };
const info = {}; pods.forEach(x => info[`${x.metadata.namespace}/${x.metadata.name}`] = {node: x.spec.nodeName, limits: (x.spec.containers||[]).map(c => ({name: c.name, memLimit: c.resources?.limits?.memory || "none", memReq: c.resources?.requests?.memory || "none", cpuLimit: c.resources?.limits?.cpu || "none"})), restarts: (x.status.containerStatuses||[]).reduce((a,c)=>a+(c.restartCount||0),0)});
let rows = (m.body.items || []).map(x => { const key = `${x.metadata.namespace}/${x.metadata.name}`; const mem = (x.containers||[]).reduce((a,c)=>a+toMi(c.usage.memory),0); const cpu = (x.containers||[]).reduce((a,c)=>a+toM(c.usage.cpu),0); return {pod: key, node: info[key]?.node, memMi: Math.round(mem), cpuM: Math.round(cpu), restarts: info[key]?.restarts, containers: info[key]?.limits, perContainer: (x.containers||[]).map(c => `${c.name}: mem=${Math.round(toMi(c.usage.memory))}Mi cpu=${Math.round(toM(c.usage.cpu))}m`)}; });
if (p.node) rows = rows.filter(r => r.node === p.node);
rows.sort((a,b) => p.sortBy === "cpu" ? b.cpuM - a.cpuM : b.memMi - a.memMi);
const totalMi = rows.reduce((a,r)=>a+r.memMi,0), totalM = rows.reduce((a,r)=>a+r.cpuM,0);
return [{json: {ok: true, node: p.node || "all nodes", sortBy: p.sortBy, podsCounted: rows.length, totalMemMi: Math.round(totalMi), totalCpuM: Math.round(totalM), top: rows.slice(0, p.limit)}}];
